# PY-331..PY-400 (continued): Functions - decorators, higher-order functions and recursion.

# ---- 20 decorators ----
DEC_IN = "First line `n`, then `n` values."
py(F, "Call Counter Decorator", "A monitoring tool wraps a function with a decorator `counted` that counts how many times it was called. For `n` calls of `square(x)` print each result, then `calls: n`.", DEC_IN, "The results then the call count.", "1 <= n <= 30",
   "def counted(fn):\n    def wrapper(*a):\n        wrapper.calls += 1\n        return fn(*a)\n\n    wrapper.calls = 0\n    return wrapper\n\n\n@counted\ndef square(x):\n    return x * x\n\n\nn = int(input())\nfor x in map(int, input().split()):\n    print(square(x))\nprint(f\"calls: {square.calls}\")", LST(-9, 9, 1, 8), edges=["1\n2\n"])
py(F, "Shout Decorator", "A chat app decorates `greet(name)` with `shout` which upper-cases the returned text. For each name print the shouted greeting `HELLO, <NAME>!`.", "First line `n`, then `n` names.", "One greeting per name.", "1 <= n <= 20",
   "def shout(fn):\n    def wrapper(*a):\n        return fn(*a).upper()\n\n    return wrapper\n\n\n@shout\ndef greet(name):\n    return f\"Hello, {name}!\"\n\n\nn = int(input())\nfor name in input().split():\n    print(greet(name))", lambda r: (lambda k: rows(k, " ".join(r.sample(NAMES_F, k))))(r.randint(1, 5)), edges=["1\nom\n"])
py(F, "Tax Decorator", "A billing function `price(x)` returns a base price. A decorator `with_tax(rate)` adds `rate` percent tax. Read `rate`, then `n` prices; print `price` after tax with two decimals.", "First line `rate`, then `n`, then `n` prices.", "One amount per price.", "0 <= rate <= 100",
   "def with_tax(rate):\n    def deco(fn):\n        def wrapper(x):\n            return fn(x) * (1 + rate / 100)\n\n        return wrapper\n\n    return deco\n\n\nrate = int(input())\n\n\n@with_tax(rate)\ndef price(x):\n    return x\n\n\nn = int(input())\nfor x in map(int, input().split()):\n    print(f\"{price(x):.2f}\")", lambda r: (lambda k: rows(r.randint(0, 28), k, " ".join(str(r.randint(10, 900)) for _ in range(k))))(r.randint(1, 6)), edges=["0\n1\n5\n"])
py(F, "Positive Only Guard", "A decorator `positive_only` makes a function print `invalid` instead of running when its argument is not positive. Apply it to `sqrt_int(x)` (integer square root) and run `n` inputs.", DEC_IN, "One line per input.", "1 <= n <= 30",
   "import math\n\n\ndef positive_only(fn):\n    def wrapper(x):\n        return fn(x) if x > 0 else \"invalid\"\n\n    return wrapper\n\n\n@positive_only\ndef sqrt_int(x):\n    return math.isqrt(x)\n\n\nn = int(input())\nfor x in map(int, input().split()):\n    print(sqrt_int(x))", LST(-5, 100, 2, 9), edges=["1\n0\n"])
py(F, "Logging Decorator", "A decorator `logged` prints `calling <name>` before running a function. Decorate `add(a, b)` and `mul(a, b)`; each input line is `add a b` or `mul a b`. Print the log line then the result.", "First line `n`, then `n` lines.", "Two lines per command.", "1 <= n <= 20",
   "def logged(fn):\n    def wrapper(*a):\n        print(\"calling\", fn.__name__)\n        return fn(*a)\n\n    return wrapper\n\n\n@logged\ndef add(a, b):\n    return a + b\n\n\n@logged\ndef mul(a, b):\n    return a * b\n\n\nops = {\"add\": add, \"mul\": mul}\nn = int(input())\nfor _ in range(n):\n    o, a, b = input().split()\n    print(ops[o](int(a), int(b)))", lambda r: (lambda n: rows(n, *[f"{r.choice(['add', 'mul'])} {r.randint(1, 20)} {r.randint(1, 20)}" for _ in range(n)]))(r.randint(1, 5)), edges=["1\nadd 1 1\n"])
py(F, "Result Rounding Decorator", "A decorator `rounded` rounds a function's result to the nearest whole number (Python `round`). Decorate `average(a, b, c)` and print the rounded average for each input line.", "First line `n`, then `n` lines of three numbers.", "One integer per line.", "1 <= n <= 20",
   "def rounded(fn):\n    def wrapper(*a):\n        return round(fn(*a))\n\n    return wrapper\n\n\n@rounded\ndef average(a, b, c):\n    return (a + b + c) / 3\n\n\nn = int(input())\nfor _ in range(n):\n    print(average(*map(int, input().split())))", lambda r: (lambda n: rows(n, *[one_line(*[r.randint(0, 100) for _ in range(3)]).strip() for _ in range(n)]))(r.randint(1, 6)), edges=["1\n1 1 1\n"])
py(F, "Memoise Decorator", "A decorator `memo` stores results of a function so repeated arguments are not recomputed. Decorate `slow_square(x)`, which counts real executions in a global. Print each result, then `computed: k` where `k` is the number of real executions.", DEC_IN, "The results, then the computation count.", "1 <= n <= 30",
   "computed = 0\n\n\ndef memo(fn):\n    cache = {}\n\n    def wrapper(x):\n        if x not in cache:\n            cache[x] = fn(x)\n        return cache[x]\n\n    return wrapper\n\n\n@memo\ndef slow_square(x):\n    global computed\n    computed += 1\n    return x * x\n\n\nn = int(input())\nfor x in map(int, input().split()):\n    print(slow_square(x))\nprint(f\"computed: {computed}\")", LST(1, 5, 3, 10), edges=["1\n2\n"])
py(F, "Retry Until Success", "A flaky service fails the first `f` times it is called and then succeeds. A decorator `retry(times)` calls the function up to `times` times and returns `success after k tries` or `failed`. Read `f times` and print the result.", "One line `f times`.", "The message.", "0 <= f <= 10, 1 <= times <= 10",
   "def retry(times):\n    def deco(fn):\n        def wrapper():\n            for k in range(1, times + 1):\n                try:\n                    return fn(k)\n                except RuntimeError:\n                    pass\n            return \"failed\"\n\n        return wrapper\n\n    return deco\n\n\nf, times = map(int, input().split())\n\n\n@retry(times)\ndef service(attempt):\n    if attempt <= f:\n        raise RuntimeError(\"down\")\n    return f\"success after {attempt} tries\"\n\n\nprint(service())", lambda r: one_line(r.randint(0, 6), r.randint(1, 6)), edges=["0 1\n", "2 2\n", "2 3\n"])
py(F, "Uppercase Result List", "A decorator `upper_all` turns every string in a returned list to upper case. Decorate `names()` which returns the input names sorted, and print them separated by spaces.", "One line of names.", "The upper-case sorted names.", "At most 20 names.",
   "def upper_all(fn):\n    def wrapper(*a):\n        return [s.upper() for s in fn(*a)]\n\n    return wrapper\n\n\n@upper_all\ndef names(items):\n    return sorted(items)\n\n\nprint(*names(input().split()))", lambda r: " ".join(r.sample(NAMES_F, r.randint(2, 6))) + "\n", edges=["a\n"])
py(F, "Admin Only Decorator", "A decorator `admin_only` runs a function only when the user's role is `admin`; otherwise it prints `Access denied`. Each input line is `role action`; the action `delete` prints `Deleted`. Print the outcome.", "First line `n`, then `n` lines `role action`.", "One line per command.", "1 <= n <= 20",
   "def admin_only(fn):\n    def wrapper(role):\n        if role != \"admin\":\n            return \"Access denied\"\n        return fn()\n\n    return wrapper\n\n\n@admin_only\ndef delete():\n    return \"Deleted\"\n\n\nn = int(input())\nfor _ in range(n):\n    role, action = input().split()\n    print(delete(role))", lambda r: (lambda n: rows(n, *[f"{r.choice(['admin', 'guest', 'editor'])} delete" for _ in range(n)]))(r.randint(1, 6)), edges=["1\nadmin delete\n"])
py(F, "Time Format Decorator", "A decorator `as_clock` converts a function's returned number of minutes into `HH:MM`. Decorate `add_minutes(start, extra)` (start and extra in minutes, wrapping past 24 hours) and print the clock time for each pair.", "First line `n`, then `n` lines `start extra`.", "One `HH:MM` per line.", "0 <= start < 1440",
   "def as_clock(fn):\n    def wrapper(*a):\n        m = fn(*a)\n        return f\"{m // 60:02d}:{m % 60:02d}\"\n\n    return wrapper\n\n\n@as_clock\ndef add_minutes(start, extra):\n    return (start + extra) % 1440\n\n\nn = int(input())\nfor _ in range(n):\n    a, b = map(int, input().split())\n    print(add_minutes(a, b))", lambda r: (lambda n: rows(n, *[f"{r.randint(0, 1439)} {r.randint(0, 3000)}" for _ in range(n)]))(r.randint(1, 5)), edges=["1\n0 0\n"])
py(F, "Argument Checker", "A decorator `ints_only` makes a function return `TypeError` when any argument is not a whole number. Decorate `add3(a, b, c)`; tokens that look like whole numbers are passed as int, other tokens as strings. Print the sum or `TypeError`.", "First line `n`, then `n` lines of three tokens.", "One line per command.", "1 <= n <= 20",
   "def ints_only(fn):\n    def wrapper(*a):\n        if not all(isinstance(x, int) for x in a):\n            return \"TypeError\"\n        return fn(*a)\n\n    return wrapper\n\n\n@ints_only\ndef add3(a, b, c):\n    return a + b + c\n\n\ndef conv(t):\n    return int(t) if t.lstrip(\"-\").isdigit() else t\n\n\nn = int(input())\nfor _ in range(n):\n    print(add3(*map(conv, input().split())))", lambda r: (lambda n: rows(n, *[one_line(*[r.choice([str(r.randint(1, 9)), str(r.randint(1, 9)), "x"]) for _ in range(3)]).strip() for _ in range(n)]))(r.randint(1, 6)), edges=["1\n1 2 3\n"])
py(F, "Stacked Decorators", "Two decorators are stacked: `double` doubles a result and `add_ten` adds 10 to a result. `value(x)` returns `x`. With `@double` above `@add_ten`, print `value(x)` for each input (so the ten is added first, then doubled).", DEC_IN, "One result per input.", "1 <= n <= 30",
   "def double(fn):\n    return lambda x: fn(x) * 2\n\n\ndef add_ten(fn):\n    return lambda x: fn(x) + 10\n\n\n@double\n@add_ten\ndef value(x):\n    return x\n\n\nn = int(input())\nprint(*(value(x) for x in map(int, input().split())))", LST(-20, 50, 2, 8), edges=["1\n0\n"])
py(F, "Preserve Function Name", "A decorator uses `functools.wraps` so the wrapped function keeps its name. Read a command `hello` or `bye`, call the matching decorated function and print its `__name__` and its result.", "One word: `hello` or `bye`.", "`name result`.", "The word is `hello` or `bye`.",
   "import functools\n\n\ndef deco(fn):\n    @functools.wraps(fn)\n    def wrapper():\n        return fn().upper()\n\n    return wrapper\n\n\n@deco\ndef hello():\n    return \"hello there\"\n\n\n@deco\ndef bye():\n    return \"goodbye\"\n\n\nf = {\"hello\": hello, \"bye\": bye}[input().strip()]\nprint(f.__name__, f())", lambda r: r.choice(["hello", "bye"]) + "\n", edges=["hello\n", "bye\n"])
py(F, "Cap the Result", "A decorator `capped(limit)` caps a function's result at `limit`. Decorate `bonus(sales)` which returns `sales // 10`. Read `limit`, then `n` sales, and print each capped bonus.", "First line `limit`, then `n`, then `n` sales.", "One bonus per sale.", "0 <= limit <= 10^6",
   "def capped(limit):\n    def deco(fn):\n        return lambda x: min(limit, fn(x))\n\n    return deco\n\n\nlimit = int(input())\n\n\n@capped(limit)\ndef bonus(sales):\n    return sales // 10\n\n\nn = int(input())\nprint(*(bonus(x) for x in map(int, input().split())))", lambda r: (lambda k: rows(r.randint(10, 500), k, " ".join(str(r.randint(0, 10000)) for _ in range(k))))(r.randint(2, 6)), edges=["0\n1\n99\n"])
py(F, "Echo Arguments Decorator", "A decorator `show_args` prints the arguments it receives as `args: a b c` before running the function. Decorate `total(*nums)` and print the total for each input line.", "First line `n`, then `n` lines of numbers.", "Two lines per input.", "1 <= n <= 10",
   "def show_args(fn):\n    def wrapper(*a):\n        print(\"args:\", *a)\n        return fn(*a)\n\n    return wrapper\n\n\n@show_args\ndef total(*nums):\n    return sum(nums)\n\n\nn = int(input())\nfor _ in range(n):\n    print(total(*map(int, input().split())))", lambda r: (lambda n: rows(n, *[one_line(*[r.randint(1, 30) for _ in range(r.randint(1, 4))]).strip() for _ in range(n)]))(r.randint(1, 4)), edges=["1\n5\n"])
py(F, "Business Hours Gate", "A decorator `business_hours` lets a function run only between 9 (inclusive) and 18 (exclusive); otherwise it returns `Closed`. Decorate `book_slot(hour)` which returns `Booked <hour>:00` and test each hour.", DEC_IN, "One line per hour.", "0 <= hour <= 23",
   "def business_hours(fn):\n    def wrapper(h):\n        return fn(h) if 9 <= h < 18 else \"Closed\"\n\n    return wrapper\n\n\n@business_hours\ndef book_slot(h):\n    return f\"Booked {h}:00\"\n\n\nn = int(input())\nfor h in map(int, input().split()):\n    print(book_slot(h))", LST(0, 23, 3, 8), edges=["2\n9 18\n"])
py(F, "Count Characters Decorator", "A decorator `length_report` returns a tuple `(result, len(result))` for a function returning text. Decorate `repeat(word, k)` returning `word * k` and print `result length` for each command.", "First line `n`, then `n` lines `word k`.", "One line per command.", "1 <= n <= 20",
   "def length_report(fn):\n    def wrapper(*a):\n        res = fn(*a)\n        return res, len(res)\n\n    return wrapper\n\n\n@length_report\ndef repeat(word, k):\n    return word * k\n\n\nn = int(input())\nfor _ in range(n):\n    w, k = input().split()\n    print(*repeat(w, int(k)))", lambda r: (lambda n: rows(n, *[f"{r.choice(['ab', 'go', 'hey', 'x'])} {r.randint(1, 5)}" for _ in range(n)]))(r.randint(1, 5)), edges=["1\na 1\n"])
py(F, "Class Decorator Counter", "A class decorator `track` gives a class a counter of how many objects were created. After creating `n` objects of `Ticket` print `created n`.", "One integer `n`.", "`created n`.", "0 <= n <= 100",
   "def track(cls):\n    cls.count = 0\n    original = cls.__init__\n\n    def init(self, *a):\n        cls.count += 1\n        original(self, *a)\n\n    cls.__init__ = init\n    return cls\n\n\n@track\nclass Ticket:\n    def __init__(self, no):\n        self.no = no\n\n\nfor i in range(int(input())):\n    Ticket(i)\nprint(f\"created {Ticket.count}\")", RI(0, 50), edges=["0\n", "1\n"])

py(F, "Timeout Guard Decorator", "A decorator `timeout_guard(limit)` marks a job as `TOO SLOW` when its reported duration (the function's return value in seconds) exceeds `limit`, otherwise `OK`. Read `limit`, then `n` durations and print the verdict for each.", "First line `limit`, then `n`, then `n` durations.", "One verdict per duration.", "0 <= limit <= 1000",
   "def timeout_guard(limit):\n    def deco(fn):\n        return lambda x: \"TOO SLOW\" if fn(x) > limit else \"OK\"\n\n    return deco\n\n\nlimit = int(input())\n\n\n@timeout_guard(limit)\ndef job(seconds):\n    return seconds\n\n\nn = int(input())\nfor s in map(int, input().split()):\n    print(job(s))", lambda r: (lambda k: rows(r.randint(5, 60), k, " ".join(str(r.randint(1, 90)) for _ in range(k))))(r.randint(2, 7)), edges=["5\n1\n5\n"])

