py(F, "Partial Function Discount", "A shop uses `functools.partial` to fix a discount of `p` percent in a function `apply(price, p)` returning the discounted price rounded down. Read `p`, then prices, and print each.", "First line `p`, then `n`, then `n` prices.", "The discounted prices separated by spaces.", "0 <= p <= 100",
   "from functools import partial\n\n\ndef apply(price, p):\n    return price * (100 - p) // 100\n\n\np = int(input())\nn = int(input())\nf = partial(apply, p=p)\nprint(*(f(x) for x in map(int, input().split())))", lambda r: (lambda k: rows(r.randint(0, 60), k, " ".join(str(r.randint(10, 999)) for _ in range(k))))(r.randint(2, 6)), edges=["0\n1\n5\n"])
